import java.text.Normalizer;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;

/**
 * A filter understood by {@link CustomerRepository}.
 *
 * <p>A customer passes the filter when it satisfies both halves of it:
 *
 * <ul>
 * <li>{@code name} is split on whitespace into terms; <em>every</em> term must
 * occur as a substring of the customer's first name or last name. Comparison
 * ignores case and accents in both directions, so {@code makinen},
 * {@code MAKINEN} and {@code mäkinen} all match {@code Mäkinen}. A blank name
 * matches every customer.
 * <li>{@code statuses} restricts the result to the selected statuses. An empty
 * selection matches every status.
 * </ul>
 *
 * <p>The filter is a value: it is what the UI hands to the backend, and what the
 * backend applies before it pages and counts.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    public CustomerFilter {
        // Leading, trailing and repeated whitespace is not significant, so two
        // filters that only differ in it are the same filter.
        name = (name == null) ? "" : name.strip().replaceAll("\\s+", " ");
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                // An EnumSet iterates in declaration order, which is the order
                // the statuses appear in the URL.
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /** {@code true} when this filter excludes nothing. */
    public boolean isEmpty() {
        return name.isEmpty() && statuses.isEmpty();
    }

    /** The name filter split into the terms that must all match. */
    public List<String> terms() {
        return name.isEmpty() ? List.of() : List.of(name.split(" "));
    }

    /** This filter as a predicate over customers. */
    public Predicate<Customer> asPredicate() {
        List<String> foldedTerms = terms().stream().map(CustomerFilter::fold).toList();
        Set<CustomerStatus> selected = statuses;
        return customer -> {
            if (!selected.isEmpty() && !selected.contains(customer.status())) {
                return false;
            }
            if (foldedTerms.isEmpty()) {
                return true;
            }
            String first = fold(customer.firstName());
            String last = fold(customer.lastName());
            return foldedTerms.stream().allMatch(term -> first.contains(term) || last.contains(term));
        };
    }

    /**
     * Folds a string down to the form the two halves of a name comparison are
     * compared in: lower case, without diacritics.
     */
    private static String fold(String value) {
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD)
                .replaceAll("\\p{M}+", "");
        // A handful of letters carry their accent inside the code point and so
        // survive decomposition; spell them out by hand.
        return decomposed
                .replace("ø", "o").replace("Ø", "O")
                .replace("đ", "d").replace("Đ", "D")
                .replace("ð", "d").replace("Ð", "D")
                .replace("ł", "l").replace("Ł", "L")
                .replace("æ", "ae").replace("Æ", "AE")
                .replace("œ", "oe").replace("Œ", "OE")

