    // --- the filter in the URL ---------------------------------------------

    @Override
    public void beforeEnter(BeforeEnterEvent event) {
        CustomerFilter fromUrl = parseFilter(event.getLocation().getQueryParameters());
        readingUrl = true;
        try {
            nameFilter.setValue(fromUrl.name());
            statusFilter.setValue(fromUrl.statuses());
        } finally {
            readingUrl = false;
        }
        applyFilter(fromUrl);
    }

    /** Reads {@code ?name=vir&status=ACTIVE,CLOSED} back into a filter. */
    static CustomerFilter parseFilter(QueryParameters parameters) {
        String name = parameters.getParameters(NAME_PARAM).stream().findFirst().orElse("");
        Set<CustomerStatus> statuses = new LinkedHashSet<>();
        for (String value : parameters.getParameters(STATUS_PARAM)) {
            for (String token : value.split(",")) {
                parseStatus(token).ifPresent(statuses::add);
            }
        }
        return new CustomerFilter(name, statuses);
    }

    private static Optional<CustomerStatus> parseStatus(String token) {
        try {
            return Optional.of(CustomerStatus.valueOf(token.strip().toUpperCase(Locale.ROOT)));
        } catch (IllegalArgumentException unknownStatus) {
            // An unreadable URL should narrow the list, not break the screen.
            return Optional.empty();
        }
    }

    /** The current filter as a query string, {@code ""} when nothing is filtered. */
    String queryString() {
        StringBuilder query = new StringBuilder();
        if (!filter.name().isEmpty()) {
            query.append(NAME_PARAM).append('=')
                    .append(URLEncoder.encode(filter.name(), StandardCharsets.UTF_8).replace("+", "%20"));
        }
        if (!filter.statuses().isEmpty()) {
            if (!query.isEmpty()) {
                query.append('&');
            }
            query.append(STATUS_PARAM).append('=')
                    .append(filter.statuses().stream().map(CustomerStatus::name)
                            .collect(Collectors.joining(",")));
        }
        return query.toString();
    }

    /**
     * Puts the current filter in the address bar, replacing the current history
     * entry rather than adding one — a filter is not a page the back button
     * should have to walk through keystroke by keystroke.
     */
    private void writeUrl() {
        getUI().ifPresent(ui -> ui.getPage().executeJs(
                "const url = new URL(window.location.href);"
                        + "url.search = $0;"
                        + "window.history.replaceState(window.history.state, '', url.toString());",
                queryString()));
    }
